{
  "compliance": [
    {"activity": "<name>", "deleted_by": "<candidate id>",
     "verdict": "must_not_delete" | "no_objection",
     "confidence": "measured|attributed|hypothesized",
     "reason": "why — and for must_not_delete, which obligation you think applies"}
